create table if not exists public.dynamo_classes(id uuid primary key default gen_random_uuid(),details jsonb not null,archived boolean not null default false,created_at timestamptz not null default now());
alter table public.dynamo_classes enable row level security;
revoke all on public.dynamo_classes from anon,authenticated;
grant select,insert,update on public.dynamo_classes to service_role;
create index if not exists dynamo_classes_public on public.dynamo_classes((details->>'status')) where not archived;
-- Preserve the two complete schedules already published on the existing Classes page.
insert into public.dynamo_classes(details) select '{"ageMode": "age", "minAgeYears": 0, "minAgeMonths": 0, "status": "Published", "options": [], "name": "Stay & Play", "category": "Stay & Play", "day": "Saturday", "start": "08:15", "end": "09:10", "duration": 55, "priceCents": 750, "description": "Members and non-members welcome. No need to book — simply turn up and pay on the door at Hamble Sports Complex."}'::jsonb where not exists(select 1 from public.dynamo_classes where details->>'name'='Stay & Play');
insert into public.dynamo_classes(details) select '{"ageMode": "age", "minAgeYears": 18, "minAgeMonths": 0, "status": "Published", "options": [{"label": "Extended single session", "start": "20:30", "end": "22:00", "duration": 90, "sessions": 1, "priceCents": 1500}, {"label": "Block of 5 — one-hour sessions", "start": "20:30", "end": "21:30", "duration": 60, "sessions": 5, "priceCents": 4000}, {"label": "Block of 3 — extended sessions", "start": "20:30", "end": "22:00", "duration": 90, "sessions": 3, "priceCents": 3750}, {"label": "Block of 5 — extended sessions", "start": "20:30", "end": "22:00", "duration": 90, "sessions": 5, "priceCents": 5000}], "name": "Adult Gymnastics", "category": "Adult Gymnastics", "day": "Thursday", "start": "20:30", "end": "21:30", "duration": 60, "priceCents": 1000, "description": "Mixed ability gymnastics with a coach-led warm up and time to use the apparatus."}'::jsonb where not exists(select 1 from public.dynamo_classes where details->>'name'='Adult Gymnastics');
